func Totals(inv core.Invoice, rules []discount.Rule, taxes tax.Table) Summary {
	s := Summarize(inv)
	for _, line := range inv.Lines {
		off := discount.Line(line, rules)
		s.Discount += off
		s.Tax += taxes.Line(line, line.Gross()-off)
	}
	s.Total = s.Subtotal - s.Discount + s.Tax
	return s
}

func Statement(inv core.Invoice, rules []discount.Rule, taxes tax.Table, rates fx.Table, currency string) (Summary, string, error) {
	if err := inv.Validate(); err != nil {
		return Summary{}, "", err
	}
	s := Totals(inv, rules, taxes)
	converted, err := rates.Convert(s.Total, inv.Currency, currency)
	if err != nil {
		return Summary{}, "", err
	}
	s.Currency = currency
	s.Converted = converted

	cols := []render.Column{
		{Title: "SKU"},
		{Title: "Qty", Right: true},
		{Title: "Unit", Right: true},
		{Title: "Discount", Right: true},
		{Title: "Tax", Right: true},
		{Title: "Amount", Right: true},
	}
	rows := make([][]string, 0, len(inv.Lines))
	for _, line := range inv.Lines {
		off := discount.Line(line, rules)
		net := line.Gross() - off
		t := taxes.Line(line, net)
		rows = append(rows, []string{
			line.SKU, strconv.FormatInt(line.Qty, 10), line.Unit.String(),
			off.String(), t.String(), (net + t).String(),
		})
	}
	total := func(label string, m core.Money) []string {
		return []string{label, "", "", "", "", m.String()}
	}
	footer := [][]string{
		total("Subtotal", s.Subtotal),
		total("Discount", s.Discount),
		total("Tax", s.Tax),
		total("Total", s.Total),
	}
	if currency != inv.Currency {
		footer = append(footer, total("Total in "+currency, s.Converted))
	}
	text := "Invoice " + inv.ID + " for " + inv.Customer + " (" + inv.Currency + ")\n" +
		render.Table(cols, rows, footer)
	return s, text, nil
}

func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

